        y=int(H*j/50); d.line([(0,y),(W,y)],fill=(80,255,80),width=1)
for i in range(1,50,2):
    x=int(W*i/50); d.text((x,5),str(i*2),fill=(255,255,0))
    y=int(H*i/50); d.text((5,y),str(i*2),fill=(255,255,0))
im.save('/tmp/grid50.png')
print('saved', im.size)
